// ShaderChain.runtime.js — the single owner of onBeforeCompile for Material3D materials.
//
// WHY THIS EXISTS
//
// `material.onBeforeCompile` is one function property, not a list. Two behaviors that both assign
// it do not compose — whichever assigns last silently wins, and the loser's shader edits never
// appear. No error, no warning, just a plausible-looking surface missing half its features.
//
// Material 3D, BRDF Material and AdvancedLighting3D all need to edit the compiled shader, and the
// planned v3.5 modules (parallax occlusion, subsurface scattering, triplanar, detail normals,
// wetness) each need it too. So nobody assigns the hook directly. Injectors register here, and this
// module owns the one hook and runs them in a declared order.
//
// CLONE SAFETY
//
// THREE.Material.copy() carries neither `onBeforeCompile` nor `customProgramCacheKey`, and it JSON
// round-trips `userData` — so anything stored there loses its prototype. Material 3D clones
// materials routinely. Therefore: all chain state lives on DIRECT material properties, and
// install() must be re-run on every clone. `isInstalled()` is how a caller checks.
//
// MATERIAL REPLACEMENT
//
// Several runtimes construct `new THREE.Mesh*Material` and swap it onto the mesh. That throws the
// hook, the cache key and the chain state away with the discarded object — silently. `ensureAll()`
// exists for this: call it on the per-frame tick and a replaced material gets re-patched instead of
// quietly losing every injector.
//
// VERSION NEGOTIATION
//
// This file is embedded in more than one extension's runtime. Each copy carries CHAIN_VERSION, and
// a newer copy replaces an older one. The registry and the tracked-material list live on
// `gdjs.__m3dShaderChainState`, NOT in this closure, so an upgrade adopts what the previous copy
// had rather than starting empty — see the comment on the migration guard below for the one case
// that cannot be migrated.

(function () {
    if (typeof gdjs === 'undefined' || typeof THREE === 'undefined') return;

    // Bump when the contract changes (new band, new injector field, new exported function).
    var CHAIN_VERSION = 2;

    var previous = gdjs.__m3dShaderChain;
    var previousVersion = previous ? (previous.VERSION || 1) : 0;

    // Same or newer already installed: leave it alone. An equal version means another extension
    // embedded this identical file; there is nothing to gain by replacing it.
    if (previous && previousVersion >= CHAIN_VERSION) return;

    // Shared across module replacements. A v1 copy kept `injectors` in its own closure and cannot
    // be read from here, so its registrations are unrecoverable — warn rather than silently drop
    // them. From v2 onward every copy uses this object and upgrades migrate cleanly.
    var shared = gdjs.__m3dShaderChainState;
    if (!shared) {
        shared = gdjs.__m3dShaderChainState = { injectors: [], tracked: [] };
    }

    if (previous && previousVersion < 2) {
        // Only ids the shared registry does NOT already hold are actually lost. A predecessor that
        // kept its injectors in the shared array (any v2+) loses nothing, so warning on its ids
        // would be a false alarm.
        var had = [];
        try { had = previous.registeredIds ? previous.registeredIds() : []; } catch (e) {}
        var lost = [];
        for (var h = 0; h < had.length; h++) {
            var known = false;
            for (var j = 0; j < shared.injectors.length; j++) {
                if (shared.injectors[j].id === had[h]) { known = true; break; }
            }
            if (!known) lost.push(had[h]);
        }
        if (lost.length) {
            console.error(
                '[Material3D] ShaderChain v' + CHAIN_VERSION + ' replaced v' + previousVersion +
                ', which kept its injector registry privately and cannot be migrated. These ' +
                'injectors are no longer registered: ' + lost.join(', ') + '. The extension that ' +
                'shipped the older ShaderChain needs updating to match. Materials already patched ' +
                'by the old copy keep working; newly created ones will be missing these effects.'
            );
        }
    }

    var injectors = shared.injectors;
    var tracked = shared.tracked;

    var HAS_WEAKREF = (typeof WeakRef === 'function');

    gdjs.__m3dShaderChain = (function () {

        // ORDER BANDS — where a new module slots in.
        //
        // Ordered low to high, and the principle is layering, not shader execution order: the
        // BASE decides how the surface responds to light, and everything after it modifies the
        // inputs that response is computed from. A module registering in a later band can assume
        // the earlier bands are already in place and integrate with them.
        //
        //   100-199  BASE SHADING     the lighting model itself           — brdf, clustered lighting
        //   200-399  UV SYNTHESIS     what texture coordinates are used   — triplanar, parallax
        //   400-599  SURFACE INPUTS   normals, roughness, albedo          — detail normals, ripples
        //   600-799  LIGHTING ADD-ONS extra light response                — subsurface, specular AA
        //   800-999  OVERRIDES        anything that must have the last word
        //
        // Two injectors in the same band editing the same chunk is allowed but must be deliberate;
        // the build prints a note when it sees a chunk claimed twice.

        /**
         * @param {object} inj
         *   id       {string}   short stable key, also used to build the program cache key
         *   chunk    {string}   the Three.js shader chunk this injector edits, for conflict checks
         *   order    {number}   sort position; ties broken by registration order
         *   isActive {function} (mat) => boolean — whether this injector applies to this material
         *   inject   {function} (shader, mat) => void — perform the edit
         *   key      {function} (mat) => string — cache-key fragment; MUST vary with anything that
         *                       changes the generated source, or Three.js will reuse a stale program
         */
        function register(inj) {
            for (var i = 0; i < injectors.length; i++) {
                if (injectors[i].id === inj.id) { injectors[i] = inj; return; }
            }
            injectors.push(inj);
            injectors.sort(function (a, b) { return (a.order || 0) - (b.order || 0); });
        }

        /** Drop an injector entirely. Materials keep their hook; the injector simply stops applying. */
        function unregister(id) {
            for (var i = 0; i < injectors.length; i++) {
                if (injectors[i].id === id) { injectors.splice(i, 1); return true; }
            }
            return false;
        }

        function activeFor(mat) {
            var out = [];
            for (var i = 0; i < injectors.length; i++) {
                var inj = injectors[i];
                try { if (inj.isActive(mat)) out.push(inj); } catch (e) {}
            }
            return out;
        }

        /* ------------------------------------------------------- Material tracking */

        // Held weakly where the runtime supports it, so a material dropped by the scene can still
        // be collected. Without WeakRef the list holds strong references and clearTracked() on
        // scene teardown is what keeps it from growing across scene changes.
        function track(mat) {
            for (var i = 0; i < tracked.length; i++) {
                if (deref(tracked[i]) === mat) return;
            }
            tracked.push(HAS_WEAKREF ? new WeakRef(mat) : mat);
        }

        function deref(entry) {
            if (!entry) return null;
            return (HAS_WEAKREF && entry instanceof WeakRef) ? (entry.deref() || null) : entry;
        }

        function forget(mat) {
            for (var i = tracked.length - 1; i >= 0; i--) {
                if (deref(tracked[i]) === mat) tracked.splice(i, 1);
            }
        }

        /**
         * Re-patch every tracked material that has lost the hook, and drop collected entries.
         *
         * This is the answer to material replacement: a runtime that swaps in a fresh
         * `new THREE.MeshStandardMaterial` leaves the old one patched and the new one bare, and
         * nothing errors. Call this once per frame from a post-events tick.
         *
         * @returns {number} how many materials were re-installed this call
         */
        function ensureAll() {
            var repaired = 0;
            for (var i = tracked.length - 1; i >= 0; i--) {
                var mat = deref(tracked[i]);
                if (!mat) { tracked.splice(i, 1); continue; }
                if (isInstalled(mat)) continue;
                if (!activeFor(mat).length) continue;
                if (install(mat)) repaired++;
            }
            return repaired;
        }

        function clearTracked() {
            tracked.length = 0;
        }

        function trackedCount() {
            var n = 0;
            for (var i = 0; i < tracked.length; i++) { if (deref(tracked[i])) n++; }
            return n;
        }

        /* ------------------------------------------------------- Install / uninstall */

        /**
         * Claim onBeforeCompile on this material. Safe to call repeatedly and REQUIRED after any
         * clone, because copy() drops the hook.
         */
        function install(mat) {
            if (!mat) return false;

            mat.onBeforeCompile = function (shader) {
                var active = activeFor(mat);
                var landed = [];
                for (var i = 0; i < active.length; i++) {
                    try {
                        active[i].inject(shader, mat);
                        landed.push(active[i].id);
                    } catch (e) {
                        // One bad injector must not cost the others their edits.
                        console.warn('[Material3D] shader injector "' + active[i].id + '" failed: ' + e.message);
                    }
                }
                // Diagnostic surface. GDevelop 3D shader work fails silently, so record what
                // actually ran and what the compiler actually received.
                mat.__m3dInjected = landed;
                mat.__m3dCompiledAt = (typeof performance !== 'undefined' && performance.now)
                    ? performance.now() : 0;
            };

            // Three.js reuses one compiled program across materials with equal cache keys. Two
            // materials with different injectors active generate different source, so the key must
            // distinguish them or one will silently render with the other's shader.
            mat.customProgramCacheKey = function () {
                var active = activeFor(mat);
                var k = 'M3D';
                for (var i = 0; i < active.length; i++) {
                    var frag;
                    try { frag = active[i].key(mat); } catch (e) { frag = '?'; }
                    k += '|' + active[i].id + ':' + frag;
                }
                return k;
            };

            mat.__m3dChainInstalled = true;
            mat.needsUpdate = true;
            track(mat);
            return true;
        }

        /**
         * Release the hook and stop tracking. Use on teardown instead of assigning a no-op
         * onBeforeCompile directly, so the material leaves the tracked list too.
         */
        function uninstall(mat) {
            if (!mat) return false;
            mat.onBeforeCompile = function () {};
            mat.customProgramCacheKey = function () { return ''; };
            mat.__m3dChainInstalled = false;
            mat.__m3dInjected = null;
            forget(mat);
            mat.needsUpdate = true;
            return true;
        }

        function isInstalled(mat) {
            return !!(mat && mat.__m3dChainInstalled === true && typeof mat.onBeforeCompile === 'function');
        }

        /** Re-install on a material that lost the hook to a clone. Returns true if it acted. */
        function ensure(mat) {
            if (!mat) return false;
            if (isInstalled(mat)) return false;
            if (!activeFor(mat).length) return false;
            return install(mat);
        }

        /** Which injector ids actually ran at the last compile. Empty until the material renders. */
        function injectedIds(mat) {
            return (mat && mat.__m3dInjected) ? mat.__m3dInjected.slice() : [];
        }

        function hasInjector(mat, id) {
            return injectedIds(mat).indexOf(id) >= 0;
        }

        /** Ids registered globally, whether or not active on any material. */
        function registeredIds() {
            return injectors.map(function (i) { return i.id; });
        }

        return {
            VERSION: CHAIN_VERSION,
            register: register,
            unregister: unregister,
            install: install,
            uninstall: uninstall,
            ensure: ensure,
            ensureAll: ensureAll,
            isInstalled: isInstalled,
            injectedIds: injectedIds,
            hasInjector: hasInjector,
            registeredIds: registeredIds,
            activeFor: activeFor,
            clearTracked: clearTracked,
            trackedCount: trackedCount,
        };
    })();

    // An upgrade inherits materials patched by the previous copy. Their hooks still close over the
    // OLD module's activeFor, so they must be re-installed against this one or they will never see
    // injectors registered from here on.
    //
    // ensureAll() is the wrong tool here: those materials still report __m3dChainInstalled === true,
    // so it would skip every one of them. Re-install unconditionally instead.
    //
    // For a v1 predecessor `tracked` is empty — v1 kept no material list — which is the other half
    // of the unmigratable-registry warning above.
    if (previous && tracked.length) {
        var stale = tracked.slice();
        for (var t = 0; t < stale.length; t++) {
            var m = (HAS_WEAKREF && stale[t] instanceof WeakRef) ? stale[t].deref() : stale[t];
            if (m) gdjs.__m3dShaderChain.install(m);
        }
    }
})();

/* ClusteredDetail: forward projected decals, Three.js r160 / WebGL2.
 * All public positions use GDevelop layer coordinates (+Z up). Matrices stored
 * on the GPU use Three world coordinates, including the layer's Y reflection.
 * ShaderChain.runtime.js is embedded by build-extension.mjs before this file.
 */
(function () {
  'use strict';
  if (typeof gdjs === 'undefined' || typeof THREE === 'undefined' || gdjs.__clusteredDetail) return;
  const NX = 16, NY = 9, NZ = 24, CELLS = NX * NY * NZ, LIMIT = 32;
  const INDEX_WIDTH = 1024, INDEX_HEIGHT = Math.ceil(CELLS * LIMIT / INDEX_WIDTH);
  const MODES = ['AlphaBlend', 'Multiply', 'NormalOnly', 'EmissiveGlow'];
  const scenes = new WeakMap();
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const number = (v, fallback) => Number.isFinite(Number(v)) ? Number(v) : fallback;
  const prop = (b, key, fallback) => typeof b['_get' + key] === 'function' ? b['_get' + key]() : fallback;
  const meshOf = o => o?.get3DRendererObject?.() || o?.getRenderer?.()?.get3DRendererObject?.() || null;
  const rendererOf = s => s.getGame?.().getRenderer?.().getThreeRenderer?.();
  function supported(scene) {
    return !!(rendererOf(scene)?.capabilities?.isWebGL2 && gdjs.__m3dShaderChain);
  }
  function texture(data, w, h, format, type, internal) {
    const t = new THREE.DataTexture(data, w, h, format, type);
    t.internalFormat = internal; t.minFilter = t.magFilter = THREE.NearestFilter;
    t.generateMipmaps = false; t.colorSpace = THREE.NoColorSpace; t.needsUpdate = true;
    return t;
  }
  function solid(r, g, b, a) { return texture(new Uint8Array([r,g,b,a]), 1, 1, THREE.RGBAFormat, THREE.UnsignedByteType, 'RGBA8'); }

  const HEADER = `
  uniform highp sampler2D cdData;
  uniform highp usampler3D cdGrid;
  uniform highp usampler2D cdIndices;
  uniform sampler2D cdAtlas;
  uniform sampler2D cdNormalAtlas;
  uniform sampler2D cdSurfaceAtlas;
  uniform vec2 cdZ;
  uniform vec3 cdChannels;
  uniform int cdMask;
  varying vec3 cdWorld;
  varying vec4 cdClip;
  vec3 cdLinear(vec3 c) {
    return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c));
  }
  // RNM in the decal's orthonormal projection frame, never mixing world/view normals.
  vec3 cdBlendNormal(vec3 base, vec3 detail) {
    vec3 t = base + vec3(0.0, 0.0, 1.0);
    vec3 u = detail * vec3(-1.0, -1.0, 1.0);
    return normalize(t * dot(t, u) / max(t.z, 0.0001) - u);
  }
  `;
  const LOOP = `
  vec2 cdScreen = cdClip.xy / cdClip.w * 0.5 + 0.5;
  float cdDepth = max(vViewPosition.z, cdZ.x);
  ivec3 cdCell = ivec3(clamp(floor(cdScreen * vec2(16.0,9.0)), vec2(0.0), vec2(15.0,8.0)),
    clamp(floor(log(cdDepth / cdZ.x) / cdZ.y * 24.0), 0.0, 23.0));
  uvec2 cdHeader = texelFetch(cdGrid, cdCell, 0).rg;
  vec3 cdGeomWorld = inverseTransformDirection(nonPerturbedNormal, viewMatrix);
  for (int cdI = 0; cdI < 32; cdI++) {
    if (uint(cdI) >= cdHeader.g) break;
    int cdAddress = int(cdHeader.r) + cdI;
    int cdSlot = int(texelFetch(cdIndices, ivec2(cdAddress % 1024, cdAddress / 1024), 0).r);
    vec4 cdR0 = texelFetch(cdData, ivec2(0,cdSlot), 0);
    vec4 cdR1 = texelFetch(cdData, ivec2(1,cdSlot), 0);
    vec4 cdR2 = texelFetch(cdData, ivec2(2,cdSlot), 0);
    vec4 cdUV = texelFetch(cdData, ivec2(3,cdSlot), 0);
    vec4 cdP = texelFetch(cdData, ivec2(4,cdSlot), 0);
    vec4 cdS = texelFetch(cdData, ivec2(5,cdSlot), 0);
    if ((int(cdS.z) & cdMask) == 0) continue;
    vec4 cdWP = vec4(cdWorld,1.0);
    vec3 cdLocal = vec3(dot(cdR0,cdWP),dot(cdR1,cdWP),dot(cdR2,cdWP));
    if (any(greaterThan(abs(cdLocal),vec3(0.5)))) continue;
    vec3 cdN = normalize(cdR2.xyz);
    float cdCos = dot(cdGeomWorld,cdN);
    if (cdCos <= cdP.x) continue;
    vec2 cdTexUV = cdUV.xy + vec2(cdLocal.x+0.5,0.5-cdLocal.y)*cdUV.zw;
    // Explicit LOD: cluster loops diverge. Atlases must have padded cells; no mip bleed.
    vec4 cdTex = textureLod(cdAtlas,cdTexUV,0.0);
    vec4 cdNT = textureLod(cdNormalAtlas,cdTexUV,0.0);
    float cdA = (int(cdP.y)==2 ? cdNT.a : cdTex.a) * cdP.z
      * clamp((cdCos-cdP.x)/(1.0-cdP.x),0.0,1.0)
      * (1.0-smoothstep(0.35,0.5,abs(cdLocal.z)));
    vec3 cdColor = cdLinear(cdTex.rgb);
    int cdMode = int(cdP.y);
    if (cdMode==0) diffuseColor.rgb = mix(diffuseColor.rgb,cdColor,cdA);
    if (cdMode==1) diffuseColor.rgb = mix(diffuseColor.rgb,diffuseColor.rgb*cdColor,cdA);
    if (cdMode==3) totalEmissiveRadiance += cdColor*cdA*cdP.w;
    if (cdChannels.x > 0.5 || cdMode==2) {
      vec3 cdT = normalize(cdR0.xyz);
      // Atlas V increases opposite local Y. Use a right handed frame, accounting for mirror.
      vec3 cdB = normalize(cross(cdN,cdT));
      float cdHand = sign(dot(cdB,-normalize(cdR1.xyz)));
      vec3 cdWN = inverseTransformDirection(normal,viewMatrix);
      vec3 cdBase = vec3(dot(cdWN,cdT),dot(cdWN,cdB),dot(cdWN,cdN));
      vec3 cdDetail = cdNT.xyz*2.0-1.0; cdDetail.y *= cdHand;
      vec3 cdRN = cdBlendNormal(cdBase,normalize(cdDetail));
      vec3 cdTarget = cdT*cdRN.x + cdB*cdRN.y + cdN*cdRN.z;
      normal = normalize(mix(normal,transformDirection(cdTarget,viewMatrix),cdA));
    }
    vec2 cdRM = textureLod(cdSurfaceAtlas,cdTexUV,0.0).rg;
    if (cdChannels.y > 0.5 || cdS.x >= 0.0)
      roughnessFactor = mix(roughnessFactor,cdChannels.y > 0.5 ? cdRM.x : cdS.x,cdA);
    if (cdChannels.y > 0.5 || cdS.y >= 0.0)
      metalnessFactor = mix(metalnessFactor,cdChannels.y > 0.5 ? cdRM.y : cdS.y,cdA);
  }
  `;
  function inject(shader, mat) {
    const state = mat.__cdState;
    Object.assign(shader.uniforms, state.manager.uniforms, {cdMask: state.maskUniform});
    shader.vertexShader = shader.vertexShader.replace('#include <common>', '#include <common>\nuniform mat4 cdCameraWorld;\nvarying vec3 cdWorld;\nvarying vec4 cdClip;');
    shader.vertexShader = shader.vertexShader.replace('#include <project_vertex>', '#include <project_vertex>\ncdWorld = (cdCameraWorld * mvPosition).xyz; cdClip = gl_Position;');
    // After ALL base input maps, before physical lighting consumes normal/roughness/emission.
    shader.fragmentShader = shader.fragmentShader.replace('#include <common>', '#include <common>\n' + HEADER);
    shader.fragmentShader = shader.fragmentShader.replace('#include <emissivemap_fragment>', '#include <emissivemap_fragment>\n' + LOOP);
  }
  gdjs.__m3dShaderChain?.register({id:'clusteredDetail', order:590, chunk:'emissivemap_fragment',
    isActive:m=>!!m.__cdState, key:()=> '2', inject});

  class Manager {
    constructor(scene, layer, capacity = 128) {
      this.scene = scene; this.layer = layer; this.capacity = capacity;
      this.slots = Array(capacity).fill(null); this.serial = 0; this.lastId = -1;
      this.columns = 4; this.rows = 4; this.timeMs = 0; this.overflow = 0;
      this.count = 0; this.frame = 0; this.preparedFrame = -1; this.preparedCamera = null;
      this.matrix = new THREE.Matrix4(); this.inverse = new THREE.Matrix4();
      this.point = new THREE.Vector3(); this.q = new THREE.Quaternion(); this.scale = new THREE.Vector3();
      this.viewBox = new THREE.Box3(); this.bounds = new THREE.Box3();
      this.cameraKey = new Float64Array(32);
      this.data = new Float32Array(6 * capacity * 4);
      this.grid = new Uint32Array(CELLS * 2);
      this.indices = new Uint16Array(INDEX_WIDTH * INDEX_HEIGHT);
      this.dataTexture = texture(this.data, 6, capacity, THREE.RGBAFormat, THREE.FloatType, 'RGBA32F');
      this.indexTexture = texture(this.indices, INDEX_WIDTH, INDEX_HEIGHT, THREE.RedIntegerFormat, THREE.UnsignedShortType, 'R16UI');
      this.gridTexture = new THREE.Data3DTexture(this.grid, NX, NY, NZ);
      Object.assign(this.gridTexture, {format:THREE.RGIntegerFormat, type:THREE.UnsignedIntType,
        internalFormat:'RG32UI', minFilter:THREE.NearestFilter, magFilter:THREE.NearestFilter,
        generateMipmaps:false, needsUpdate:true});
      this.atlases = [solid(255,255,255,0),solid(128,128,255,255),solid(255,0,0,255)];
      this.uniforms = {cdData:{value:this.dataTexture}, cdGrid:{value:this.gridTexture},
        cdIndices:{value:this.indexTexture}, cdAtlas:{value:this.atlases[0]},
        cdNormalAtlas:{value:this.atlases[1]}, cdSurfaceAtlas:{value:this.atlases[2]},
        cdZ:{value:new THREE.Vector2(0.1,1)}, cdChannels:{value:new THREE.Vector3()},
        cdCameraWorld:{value:new THREE.Matrix4()}};
    }
    root() { return this.scene.getLayer(this.layer).getRenderer().getThreeScene(); }
    spawn(options = {}) {
      let slot = this.slots.indexOf(null);
      if (slot < 0) {
        let oldest = Infinity;
        for (let i=0;i<this.capacity;i++) if (!this.slots[i].pinned && this.slots[i].id<oldest) {oldest=this.slots[i].id;slot=i;}
      }
      if (slot < 0) {this.lastId=-1;return -1;}
      const life = number(options.lifetime,30);
      const decal = {id:++this.serial, age:0, lifetime:life, pinned:options.pinned ?? life<0,
        fade:Math.max(0,number(options.fade,1)), opacity:clamp(number(options.opacity,1),0,1),
        atlas:Math.max(0,Math.floor(number(options.atlas,0))), mode:Math.max(0,MODES.indexOf(options.mode)),
        cutoff:Math.cos(clamp(number(options.cutoff,60),0.1,89.9)*Math.PI/180),
        emissive:Math.max(0,number(options.emissive,1)), mask:clamp(number(options.mask,1)|0,0,65535),
        roughness:clamp(number(options.roughness,-1),-1,1), metalness:clamp(number(options.metalness,-1),-1,1),
        matrix:new THREE.Matrix4(), inverse:new THREE.Matrix4(), center:new THREE.Vector3(), radius:0};
      this.slots[slot]=decal;
      if (options.matrix) decal.matrix.copy(options.matrix);
      else {
        this.point.set(number(options.x,0),number(options.y,0),number(options.z,0));
        if (options.normal) {
          const n = new THREE.Vector3(...options.normal);
          if (n.lengthSq()<1e-12 || !Number.isFinite(n.lengthSq())) n.set(0,0,1);
          this.q.setFromUnitVectors(new THREE.Vector3(0,0,1),n.normalize());
        } else this.q.setFromEuler(new THREE.Euler(...['rx','ry','rz'].map(k=>number(options[k],0)*Math.PI/180),'XYZ'));
        this.scale.set(...['width','height','depth'].map(k=>Math.max(0.001,Math.abs(number(options[k],10)))));
        decal.matrix.compose(this.point,this.q,this.scale);
        const root=this.root();root.updateMatrixWorld(true);decal.matrix.premultiply(root.matrixWorld);
      }
      this.updateTransform(decal); this.lastId=decal.id;this.frame++;
      this.count=this.slots.reduce((n,d)=>n+!!d,0);
      return decal.id;
    }
    updateTransform(d) {
      d.inverse.copy(d.matrix).invert();d.center.setFromMatrixPosition(d.matrix);
      // Sum of axis lengths is conservative even under sheared parents.
      const e=d.matrix.elements;
      d.radius=0.5*(Math.hypot(e[0],e[1],e[2])+Math.hypot(e[4],e[5],e[6])+Math.hypot(e[8],e[9],e[10]));
    }
